    $('deploy-btn').onclick=()=>{$('intro-overlay').classList.remove('open');running=true;alive=true;toast('OPERAÇÃO INICIADA // WARDEN DETECTADO')};$('shop-open').onclick=openShop;$('shop-close').onclick=closeShop;document.querySelectorAll('.shop-categories button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.shop-categories button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderShop(b.dataset.filter)});$('sound-btn').onclick=()=>{muted=!muted;$('sound-btn').style.color=muted?'#71818d':'#c2d5e0'};
    renderShop('all');updateHud();$('intro-overlay').classList.add('open');$('crosshair-hint').classList.add('show');connect();requestAnimationFrame(frame);
